$('#renameNet').onclick=()=>{if(draft.length){toast('Finish or cancel the trace first.',true);return}const from=activeNet(),to=netInput('#renameNetTo');if(!from||!to)return;try{commit(()=>P.renameNet(project,activeLayer,from,to),'Net renamed on the '+activeLayer+' layer.');$('#activeNet').value=to;$('#renameNetTo').value='';syncRoutingPicker()}catch(e){toast(e.message,true)}};
$('#routingNetSelect').onchange=()=>{if(draft.length)return;if($('#routingNetSelect').value)$('#activeNet').value=$('#routingNetSelect').value};$('#activeNet').oninput=syncRoutingPicker;
for(const b of document.querySelectorAll('[data-tool]'))b.onclick=()=>setTool(b.dataset.tool);$('#layerTop').onclick=()=>setLayer('top');$('#layerBottom').onclick=()=>setLayer('bottom');$('#finishTrace').onclick=finishDraft;$('#cancelTrace').onclick=cancelDraft;$('#clearSelection').onclick=clearSelection;$('#applyTop').onclick=()=>assignLayer('top','#topNet');$('#applyBottom').onclick=()=>assignLayer('bottom','#bottomNet');$('#applyPair').onclick=assignPair;$('#assignActive').onclick=()=>{const net=activeNet();if(!net){toast('Choose a routing net first.',true);return}commit(()=>{for(const id of selected)project.assignments[id][activeLayer]=net},'Assigned routing net to selection.')};$('#applyPad').onclick=()=>assignPad(netInput('#padNet'));$('#padUseActive').onclick=()=>{let n=activeNet();if(n)assignPad(n);else toast('Choose a routing net first.',true)};$('#clearPad').onclick=()=>assignPad('');$('#findPad').onclick=()=>{const id=$('#padSearch').value.trim().toUpperCase(),p=P.getPort(project,id);if(!p){toast('Pad ID not found. Example: T-N001 or B-W016.',true);return}choosePad(id);focusBounds([p.x-100,p.y-100,p.x+100,p.y+100])};$('#padSearch').onkeydown=e=>{if(e.key==='Enter')$('#findPad').click()};$('#applyWidth').onclick=()=>{const w=+$('#editWidth').value;if(!Number.isFinite(w)||w<.005||w>10){toast('Width must be 0.005–10 mm.',true);return}const t=project.traces.find(t=>t.id===selectedTrace);if(!t)return;let result;commit(()=>{t.widthMm=w;result=G.autoAssignTouched(project,D,t,{preservePadNets:true})});assignmentToast('Trace width updated.',result)};$('#deleteTrace').onclick=()=>deleteTrace(selectedTrace);
$('#segmentSearch').oninput=populateSegments;$('#segmentList').onchange=e=>chooseSegment(e.target.value);$('#prevSegment').onclick=()=>moveSegment(-1);$('#nextSegment').onclick=()=>moveSegment(1);$('#segmentSearch').onkeydown=e=>{if(e.key==='Enter'){const id=$('#segmentList').options[0]?.value;if(id){chooseSegment(id);focusBounds(byId.get(id).bounds)}}};
for(const [id,key]of [['showTop','top'],['showBottom','bottom'],['showOriginal','original'],['showChanges','changes'],['showErrors','errors'],['showGrid','grid'],['snap','snap']])$('#'+id).onchange=e=>{view[key]=e.target.checked;render()};$('#zoomIn').onclick=()=>zoom(1.4);$('#zoomOut').onclick=()=>zoom(1/1.4);$('#fit').onclick=fit;$('#check').onclick=requestCheck;$('#autoCheck').onchange=scheduleCheck;$('#issueFilter').onchange=()=>{renderIssues();render()};$('#downloadReport').onclick=()=>{if(reportRevision===revision)download(filename()+'.check.json',JSON.stringify(report,null,2))};
$('#applySettings').onclick=()=>{const candidate=P.clone(project);candidate.settings={widthMm:+$('#panelWidth').value,padSizeMm:+$('#padSize').value,clearanceMm:+$('#clearance').value,gridMm:+$('#gridSize').value};try{P.validate(candidate,BASE);commit(()=>project.settings=candidate.settings,'Dimensions changed. Physical trace widths were preserved.')}catch(e){toast(e.message,true)}};
for(const [id,layer]of [['exportTop','top'],['exportBottom','bottom']])$('#'+id).onclick=()=>{try{download(filename()+'.'+layer+'.svg',G.exportSVG(project,D,layer),'image/svg+xml');toast('Exported assigned '+layer+' conductors in front-view coordinates.')}catch(e){toast('Export failed: '+e.message,true)}};
$('#exportNetlist').onclick=()=>{const rows=[['type','id','layer','net','top_net','bottom_net','x_mm','y_mm','width_mm','original_group','game_bit']];for(const s of D.segments)rows.push(['segment',s.id,'','',project.assignments[s.id].top,project.assignments[s.id].bottom,'','','',s.parentId,s.bit]);for(const [id,net]of Object.entries(project.pads)){const p=P.getPort(project,id);rows.push(['pad',id,p.layer,net,'','',p.x*mm(),p.y*mm(),p.widthMm,'',''])}for(const t of project.traces)rows.push(['trace',t.id,t.layer,t.net,'','','','',t.widthMm,'','']);const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');download(filename()+'.netlist.csv',csv,'text/csv')};
window.addEventListener('keydown',e=>{if(pointDrag||sliceDrag||shapeDrag){if(e.key==='Escape'){e.preventDefault();cancelPointDrag()}return}const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='o'){e.preventDefault();$('#fileInput').click();return}if(typing)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return}if(e.code==='Space'){e.preventDefault();space=true;return}if(e.key==='Escape'){sliceStart=null;cancelDraft();return}if(e.key==='Enter'&&draft.length){e.preventDefault();finishDraft();return}if(e.key==='Delete'||e.key==='Backspace'){if(selectedTrace){e.preventDefault();deleteTrace(selectedTrace)}return}const mode={f:'finetune',w:'wanted',s:'slice',c:'count',v:'select',r:'draw',e:'erase',h:'pan'}[e.key.toLowerCase()];if(mode)setTool(mode)});window.addEventListener('keyup',e=>{if(e.code==='Space')space=false});window.addEventListener('blur',()=>{cancelPointDrag();space=false;panDrag=null});
new ResizeObserver(resize).observe($('#canvasHost'));rebuildArtwork();syncUI();setupWorker();requestCheck();
// Public, validated access for reproducible project checks and browser tests.
window.RouterApp={getProject:()=>P.clone(project),loadObject,selectSegment:chooseSegment,selectPad:choosePad,getReport:()=>reportRevision===revision?report:null,check:requestCheck,worldToScreen:p=>({x:camera.x+p[0]*camera.scale,y:camera.y+p[1]*camera.scale}),camera:()=>({...camera}),undo,redo};

function findSegmentById(){const query=$('#quickSegmentSearch').value.trim().toUpperCase();if(!query){toast('Enter a segment or island ID, for example C01S184.',true);return}const exact=D.segments.filter(s=>s.id.toUpperCase()===query),parent=D.segments.filter(s=>s.parentId.toUpperCase()===query);const matches=parent.length?parent:exact.length?exact:D.segments.filter(s=>s.id.toUpperCase().includes(query));if(!matches.length){toast('No segment matches '+query+'.',true);return}setTool('select');clearSelection();for(const s of matches)selected.add(s.id);$('#segmentSearch').value=query;populateSegments();syncInspector();const bs=matches.map(s=>s.bounds);focusBounds([Math.min(...bs.map(b=>b[0])),Math.min(...bs.map(b=>b[1])),Math.max(...bs.map(b=>b[2])),Math.max(...bs.map(b=>b[3]))]);toast(matches.length===1?'Found '+matches[0].id:'Found '+matches.length+' islands for '+query+'.');}
$('#findSegment').onclick=findSegmentById;
$('#quickSegmentSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();findSegmentById()}};

for(const id of ['topNet','bottomNet'])$('#'+id).readOnly=true;
for(const id of ['reassignNets','renameNet','applyTop','applyBottom','applyPair','assignActive']){$('#'+id).disabled=true;$('#'+id).title='Segment nets are frozen from Step 1 finished routing';}
$('#reassignResult').textContent='Segment nets are locked to Step 1 finished routing. Touching traces never reassign them.';

$('#exportDXF').onclick=()=>{try{const layers=[['dxfTop','TOP'],['dxfBottom','BOTTOM'],['dxfSegment','SEGMENT']].filter(([id])=>$('#'+id).checked).map(([,name])=>name);download(filename()+'.v2.dxf',RouterDXF.exportDXF(project,D,layers),'application/dxf');toast('DXF exported: '+layers.join(', ')+' · mm, registered front view.')}catch(e){toast('DXF export failed: '+e.message,true)}};

// Contact edits leave traces and frozen island nets unchanged.
let contactDrag=null;
function cancelContactDrag(){if(!contactDrag)return;const d=contactDrag;project.padPositions=d.before;contactDrag=null;if(canvas.hasPointerCapture(d.pointerId))canvas.releasePointerCapture(d.pointerId);render();}
canvas.addEventListener('pointerdown',e=>{if(tool!=='move-island'||e.button!==0||space)return;const q=worldPoint(e),pad=nearestPad(q,null);if(!pad)return;e.preventDefault();e.stopImmediatePropagation();choosePad(pad.id);contactDrag={id:pad.id,pointerId:e.pointerId,start:q,origin:[pad.x,pad.y],ports:P.getPorts(project),before:P.clone(project.padPositions||{})};canvas.setPointerCapture(e.pointerId);},true);
canvas.addEventListener('pointermove',e=>{if(!contactDrag)return;e.preventDefault();e.stopImmediatePropagation();const d=contactDrag,q=worldPoint(e),g=project.settings.gridMm/mm();let x=d.origin[0]+q[0]-d.start[0],y=d.origin[1]+q[1]-d.start[1];if(view.snap&&!e.altKey){x=Math.round(x/g)*g;y=Math.round(y/g)*g;}const [dx,dy]=constrainMoveAxis(d,[x-d.origin[0],y-d.origin[1]],e.shiftKey);project.padPositions=Object.fromEntries(d.ports.map(p=>[p.id,{x:p.x+dx,y:p.y+dy}]));render();},true);
canvas.addEventListener('pointerup',e=>{if(!contactDrag)return;e.preventDefault();e.stopImmediatePropagation();const d=contactDrag,next=P.clone(project.padPositions||{});project.padPositions=d.before;contactDrag=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);commit(()=>project.padPositions=next,'All contacts moved together. Traces remain in place.');},true);
canvas.addEventListener('pointercancel',cancelContactDrag,true);
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&contactDrag){e.preventDefault();e.stopImmediatePropagation();cancelContactDrag();}},true);
$('#resetZebra').onclick=()=>{cancelContactDrag();commit(()=>{project.contactLayout='zebra';project.padPositions={};},'Centered 16 COM + 2 empty + 48 SEG contacts. Traces stay fixed.');fit();};
if(project.contactLayout!=='zebra')commit(()=>{project.contactLayout='zebra';project.padPositions={};},'Zebra contacts arranged below the display. Traces stay fixed; Undo restores the previous layout.');
